async function walk(dir) {
  return (await Promise.all((await fs.readdir(dir, {withFileTypes:true})).map(e => e.isDirectory() ? walk(path.join(dir,e.name)) : path.join(dir,e.name)))).flat();
}
function callEnd(source,start) {
  let depth=0,quote=null;
  for(let i=start;i<source.length;i++) {
    const c=source[i];
    if(quote){if(c==='\\')i++;else if(c===quote)quote=null;}
    else if(c==='"'||c==="'"||c==='`')quote=c;
    else if(c==='(')depth++;
    else if(c===')'&&--depth===0)return i+1;
  }
  throw new Error('Unclosed component');
}
function stripHtml(source,cls) {
  const pattern=new RegExp('<div\\b[^>]*class="'+cls+'(?: [^"]*)?"[^>]*>');
  for(let m;(m=pattern.exec(source));){
    const tags=/<\/?div\b[^>]*>/g;tags.lastIndex=m.index;let depth=0,end;
    for(let t;(t=tags.exec(source));){depth+=t[0].startsWith('</')?-1:1;if(!depth){end=tags.lastIndex;break;}}
    if(!end)throw new Error('Unclosed HTML '+cls);
    source=source.slice(0,m.index)+source.slice(end);
  }
  return source;
}
function stripRuntime(source,cls,opening) {
  let index;
  while((index=source.indexOf('className:`'+cls+'`'))>=0) {
    const start=source.lastIndexOf(opening,index);
    if(start<0)throw new Error('Cannot find '+cls);
    const end=callEnd(source,start);
    if(end<=index)throw new Error('Wrong component '+cls);
    source=source.slice(0,start)+'null'+source.slice(end);
  }
  return source;
}

