for(const file of await walk(root)) {
  if(!/\.(html|mjs|js|json)$/.test(file))continue;
  let source=await fs.readFile(file,'utf8'),original=source;
  for(const [from,to] of replacements)source=source.replaceAll(from,to);
  source=source.replaceAll(assets+'brands/ecommerce.svg',assets+'brands/ecommerce-v4.svg').replaceAll(assets+'brands/automotive.svg',assets+'brands/automotive-v4.svg');
  source=source.replaceAll('href:`linkedin.com`','href:`'+linkedin+'`').replace(/href="(?:https?:\/\/)?(?:www\.)?linkedin\.com\/?"/g,'href="'+linkedin+'"');
  if(file.endsWith('.html'))for(const cls of ['framer-x10igc-container','framer-t0w5in','framer-13ouwzq','framer-1uec0m0-container'])source=stripHtml(source,cls);
  if(file.endsWith('.html')&&(file===path.join(root,'index.html')||file===path.join(root,'about/index.html'))) {
    source=source.replace(/<meta\b[^>]*(?:name|property)="twitter:[^"]*"[^>]*>/g,'');
    if(!source.includes('site/full-navigation.mjs'))source=source.replace('</head>','<script type="module" src="'+assets+'site/full-navigation.mjs"></script></head>');
  }
  if(file.endsWith('script_main.BK46AqcI.mjs')) {
    source=stripRuntime(source,'framer-x10igc-container','p(z,{height:37');
    source=stripRuntime(source,'framer-t0w5in','p(F,{__fromCanvasComponent:');
    source=stripRuntime(source,'framer-13ouwzq','p(F,{__fromCanvasComponent:');
  }
  if(file.endsWith('dESoeHb0xIHzCHT-Dsu0_g-I9OZDFxNnM4PT-YVvuzc.DgrkVucZ.mjs'))source=stripRuntime(source,'framer-1uec0m0-container','a(C,{height:37');
  if(file.endsWith('U9hXp3FhJUFJvSByVzTcrUPkEKEDb4nTk19FGJYLJi8.NaeZvDH5.mjs')) {
    const counters={v2hhixoGP:{end:50,prefix:'$',suffix:'K+'},Y_XMyI8Vc:{end:50,prefix:'',suffix:'+'},QTUeFgCqN:{end:3,prefix:'',suffix:''},pnLkXOIBb:{end:2,prefix:'',suffix:''}};
    source=source.replace(/u\(De,\{[\s\S]*?textSize:56,width:`100%`\}\)/g,m=>{
      const id=m.match(/id:`([^`]+)`/)?.[1],c=counters[id];
      if(!c)return m;
      return m.replace(/end:\d+/,()=> 'end:'+c.end).replace(/prefixText:`[^`]*`/,()=> 'prefixText:`'+c.prefix+'`').replace(/suffixText:`[^`]*`/,()=> 'suffixText:`'+c.suffix+'`').replace(/prefixColor:`[^`]*`/,'prefixColor:`var(--token-2007957d-a074-4c0c-8a33-8d85ed1ba0fd, rgb(0, 0, 0))`');
    });
  }
  if(file.endsWith('.html')&&file===path.join(root,'index.html')) {
    const counters={'framer-etnrh3-container':['$','K+'],'framer-1wjy1g3-container':['','+'],'framer-1en2zgk-container':['',''],'framer-2mlafq-container':['','']};
    const color='var(--token-2007957d-a074-4c0c-8a33-8d85ed1ba0fd, rgb(0, 0, 0))';
    for(const [cls,[prefix,suffix]] of Object.entries(counters)) {
      const pattern=new RegExp('(<div class="'+cls+'">(?:<!--\\$-->)?<div style="[^"]*">)[\\s\\S]*?(</div>(?:<!--/\\$-->)?</div>)');
      source=source.replace(pattern,(_,a,b)=>a+(prefix?`<span style="font-family:&quot;Inter&quot;, &quot;Inter Placeholder&quot;, sans-serif;font-weight:500;color:${color}">${prefix}</span>`:'')+'<span>0</span>'+(suffix?`<span style="color:${color}">${suffix}</span>`:'')+b);
    }
    source=source.replaceAll('>Award</p>','>Milestone</p>');
  }
  if(file.endsWith('.html'))source=source.replaceAll('>Award</p>','>Milestone</p>');
  if(file.endsWith('.mjs'))source=source.replaceAll('children:`Award`','children:`Milestone`');
  if(source!==original)await fs.writeFile(file,source);
}

