await fs.writeFile(path.join(root,'assets/run-more-ads/site/full-navigation.mjs'),`
// Retained Framer pages must open the completed standalone pages instead of stale template routes.
window.addEventListener('click',event=>{
 if(event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;
 const link=event.target.closest?.('a[href]');if(!link||link.hasAttribute('download')||link.target==='_blank')return;
 const url=new URL(link.href,location.href);if(url.origin!==location.origin||url.hash)return;
 const route=url.pathname.replace(/\\/$/,'');
 if(!/^\\/(?:case-studies|blog|book-a-call|privacy-policy|terms-of-service|404)(?:\\/|$)/.test(route))return;
 event.preventDefault();event.stopImmediatePropagation();location.assign(url.href);
},true);
`);
await fs.writeFile(path.join(root,'assets/run-more-ads/site/pages.mjs'),`
const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('#site-nav');
toggle?.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close navigation':'Open navigation');nav.classList.toggle('open',open)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){toggle?.setAttribute('aria-expanded','false');nav?.classList.remove('open')}});
for(const link of nav?.querySelectorAll('a')??[]){if(link.pathname===location.pathname.replace(/\\/$/,'')||link.pathname==='/'&&location.pathname==='/')link.setAttribute('aria-current','page')}
const form=document.querySelector('#contact-form');
if(matchMedia('(prefers-reduced-motion: reduce)').matches)for(const video of document.querySelectorAll('video[autoplay]'))video.pause();
let requestId=crypto.randomUUID(),sending=false;
form?.addEventListener('submit',async e=>{e.preventDefault();if(sending||!form.reportValidity())return;const status=document.querySelector('#form-status'),button=form.querySelector('[type=submit]');const show=(text,state)=>{status.hidden=false;status.textContent=text;status.dataset.state=state;status.focus()};const data=new FormData(form);sending=true;button.disabled=true;button.querySelector('span').textContent='Sending…';status.hidden=true;try{const config=await fetch('/assets/run-more-ads/site/crm-config.json',{signal:AbortSignal.timeout(10000)}).then(r=>r.ok?r.json():null);if(!config?.endpoint){show('The booking form is temporarily unavailable. Please contact us on Instagram or LinkedIn. Your request has not been submitted.','error');return}const response=await fetch(config.endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:String(data.get('name')).trim(),email:String(data.get('email')).trim(),service:data.get('service'),budget:data.get('budget'),message:String(data.get('message')).trim(),website_confirm:data.get('website_confirm'),request_id:requestId,source:'Run More Ads Website',country:'Azerbaijan',page:location.origin+location.pathname}),signal:AbortSignal.timeout(20000)});const receipt=await response.json().catch(()=>null);if(!response.ok||receipt?.ok!==true||receipt?.request_id!==requestId)throw new Error('No confirmed receipt');show('Thank you — your request has been received. Our team will contact you to arrange your call.','success');form.reset();requestId=crypto.randomUUID()}catch{show('We could not confirm your request. Please try again. Your details are still here.','error')}finally{sending=false;button.disabled=false;button.querySelector('span').textContent='Book a call'}});
`);
async function page(route,title,description,body,{withCta=true}={}) {
  const dir=path.join(root,route);await fs.mkdir(dir,{recursive:true});
  const canonical='https://run-more-ads-nihad.vividmug4.chatgpt.site/'+route;
  const html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(title)} — Run More Ads</title><meta name="description" content="${esc(description)}"><link rel="canonical" href="${canonical}"><meta property="og:title" content="${esc(title)} — Run More Ads"><meta property="og:description" content="${esc(description)}"><meta property="og:type" content="website"><meta property="og:image" content="https://run-more-ads-nihad.vividmug4.chatgpt.site${assets}brand/run-more-ads-original.png"><link rel="icon" href="${assets}brand/run-more-ads-logo-v3.svg"><link rel="stylesheet" href="${assets}site/pages.css"><script type="module" src="${assets}site/pages.mjs"></script></head><body>${nav}<main class="page">${body}${withCta?cta:''}</main>${footer}</body></html>`;
  await fs.writeFile(path.join(dir,'index.html'),html);
}

const cases=[
 {slug:'ecommerce',legacy:'border',title:'Ecommerce',category:'Online retail',video:'ecommerce',secondary:'digital-store',brand:'ecommerce',summary:'A product-first story designed to turn everyday browsing into a clear next step.',challenge:'A shopper has seconds to understand what is being sold and why it matters. The creative needs a recognisable shopping moment, a focused benefit, and a simple path to the product.',strategy:'The existing mobile-shopping footage becomes the opening visual. Pair it with one product benefit, a concise offer, and a final shop-now frame. Keep the message readable without sound and build the landing page around the same offer.',hook:'Find your next everyday favourite.',cta:'Explore the collection',measure:'Product-page visits, add-to-cart rate, purchases, and cost per purchase.',format:'Product discovery'},
 {slug:'automotive',legacy:'theo',title:'Automotive',category:'Automotive',video:'automotive',secondary:'automotive',brand:'automotive',summary:'A cinematic driving moment, shaped into a focused automotive ad concept.',challenge:'Beautiful footage can attract attention without creating a qualified enquiry. An automotive ad needs to connect the feeling of the drive to a specific vehicle, service, or appointment.',strategy:'Lead with the red sports car in motion, then introduce a single proposition: discover the vehicle or book a service. End with the next step and the information a buyer needs. Separate awareness creative from enquiry-focused variations.',hook:'Make the next drive count.',cta:'Enquire about your next drive',measure:'Qualified enquiries, appointment requests, and cost per qualified lead.',format:'Motion & aspiration'},
 {slug:'beauty-studio',legacy:'glowhaus',title:'Beauty Studio',category:'Beauty & personal care',video:'beauty-studio',secondary:'beauty-creative',summary:'An authentic beauty routine with a message built around confidence and clarity.',challenge:'Beauty creative needs to feel human while explaining the service or product clearly. Overloaded promises and generic visuals make it harder for someone to understand whether the offer is right for them.',strategy:'Use the mirror and makeup footage as a familiar opening moment. Introduce one service or product benefit, show the experience, and finish with a booking or discovery prompt. Use readable captions and avoid unsupported product claims.',hook:'A little time for you.',cta:'Discover your next beauty appointment',measure:'Booking-page visits, appointment enquiries, and cost per booking.',format:'Routine & experience'},
 {slug:'coffee-brand',legacy:'snapshot',title:'Coffee Brand',category:'Food & beverage',video:'coffee-brand',secondary:'product-detail',summary:'Close-up coffee footage that gives a simple product story a sensory opening.',challenge:'A food or drink brand must make the product desirable quickly. The ad should connect the visual to a clear reason to visit, order, or discover the range.',strategy:'Open on the cappuccino pour, follow with a product detail, and introduce one offer. A local café version can focus on a visit; an ecommerce version can lead to the coffee collection. Keep each version focused on one action.',hook:'Your next favourite coffee starts here.',cta:'Explore the coffee collection',measure:'Menu or product visits, online orders, and cost per order.',format:'Sensory product story'}
];
function card(c) {return `<a class="work-card" href="/case-studies/${c.slug}"><div class="card-media"><video muted playsinline loop autoplay preload="metadata" poster="${assets}videos/${c.video}.jpg" aria-label="${esc(c.title)} creative preview"><source src="${assets}videos/${c.video}.mp4" type="video/mp4"></video><span class="badge">${esc(c.category)}</span></div><div class="card-title"><div>${c.brand?`<img src="${assets}brands/${c.brand}-v4.svg" alt="">`:''}<h3>${esc(c.title)}</h3></div><span class="arrow" aria-hidden="true">↗</span></div><p>${esc(c.summary)}</p></a>`;}
await page('case-studies','Case Studies','Explore video creative concepts for ecommerce, automotive, beauty, and coffee brands.',`<div class="intro"><span class="eyebrow">Case studies</span><h1>Creative built for<br><em>the next step.</em></h1><p>A closer look at how we shape video footage into clear advertising ideas, with a hook, a message, and a purpose.</p><p class="muted">Creative concepts using the footage featured on our site. These examples show our approach; they do not report client campaign results.</p></div><div class="grid">${cases.map(card).join('')}</div>`);
for(const c of cases) {
  await page('case-studies/'+c.slug,c.title+' — Creative Case Study',c.summary,`<a class="back" href="/case-studies">← All case studies</a><div class="intro"><span class="eyebrow">Creative case study</span><h1>${esc(c.title)}</h1><p>${esc(c.summary)}</p></div><div class="meta"><div><span>Category</span>${esc(c.category)}</div><div><span>Platforms</span>Facebook & Instagram</div><div><span>Format</span>${esc(c.format)}</div><div><span>Type</span>Creative concept</div></div><video class="detail-video" controls playsinline preload="metadata" poster="${assets}videos/${c.video}.jpg" aria-label="${esc(c.title)} video"><source src="${assets}videos/${c.video}.mp4" type="video/mp4">Your browser does not support video playback.</video><div class="case-copy"><h2>The brief</h2><p>${esc(c.challenge)}</p></div><div class="case-copy"><h2>The creative<br><em>direction.</em></h2><p>${esc(c.strategy)}</p></div><div class="deliverables"><div class="deliverable"><span>01 / Opening hook</span><h3>${esc(c.hook)}</h3><p>An example opening line to test with this footage.</p></div><div class="deliverable"><span>02 / Next step</span><h3>${esc(c.cta)}</h3><p>One action, aligned with the offer and the destination.</p></div><div class="deliverable"><span>03 / Measurement</span><h3>Track what matters.</h3><p>${esc(c.measure)}</p></div></div><p class="muted">This is a creative concept using licensed stock footage already featured on our site. Performance is measured after a campaign launches; no client results are claimed here.</p><section class="related"><h2>More creative <em>ideas.</em></h2><div class="grid">${cases.filter(x=>x.slug!==c.slug).slice(0,2).map(card).join('')}</div></section>`);
}

const articles=[
 {slug:'how-to-create-content-that-actually-converts',title:'How to Create Content That Actually Converts',category:'Creative strategy',description:'Give every ad a job: a clear message, a relevant offer, and a useful next step.',video:'creative-studio',sections:[['Start with one action','Before writing a script, decide what the viewer should do next. A product ad might lead to a collection; a service ad might lead to an enquiry. A clear destination makes it easier to choose the message and the call to action.'],['Lead with the customer’s situation','Open with something the audience recognises: a routine, a problem, or a product in use. Then explain one benefit in language a customer would use. Avoid trying to fit every feature into a short video.'],['Make the offer and destination agree','An ad that promises a specific service should land on a page that explains that service. Use the same offer, visual language, and next step. This helps the viewer carry their interest through to the website.'],['Test a useful difference','Compare different opening moments, benefits, or calls to action. Change one major idea at a time so the result is easier to interpret. Keep the version that helps the business goal, rather than the one that only attracts views.']]},
 {slug:'beauty-ad-creative-strategy',legacy:'how-we-scaled-a-beauty-brand-to-100k',title:'A Practical Creative Strategy for Beauty Ads',category:'Beauty creative',description:'Build beauty creative around familiar routines, a clear benefit, and a relevant booking or shopping prompt.',video:'beauty-studio',sections:[['Begin with a familiar moment','A mirror, a routine, or a relaxed appointment can make a useful starting point. The viewer should understand the scene quickly. Our Beauty Studio creative case study uses the existing makeup footage to show this approach.'],['Choose one benefit','Focus each ad on one product or service and one reason to consider it. Keep the wording specific to the offer. Avoid invented before-and-after outcomes, unsupported health claims, or promises that the product cannot substantiate.'],['Build variations around the same offer','Try a routine-led opening, a product close-up, and a direct service introduction. Use readable captions and a clear closing frame. Each version should lead to the same booking or product destination.'],['Connect creative to the next step','A booking page should make the service, location, and contact route easy to find. A product page should show the product and buying information. Review appointment enquiries or purchases alongside the creative metrics.']]},
 {slug:'what-to-track-beyond-vanity-metrics',title:'What to Track Beyond Vanity Metrics',category:'Campaign measurement',description:'Connect creative performance to useful business signals, from clicks to qualified enquiries and purchases.',video:'campaign-strategy',sections:[['Define the business goal','Reach and video views describe attention. They do not, by themselves, tell you whether the campaign has helped the business. Start with the outcome you want: a qualified enquiry, an appointment, or a purchase.'],['Look at the whole journey','Review how people move from the ad to the destination and then to the next action. Compare link clicks with landing-page visits, completed enquiries, and purchases. A strong ad cannot compensate for a confusing destination.'],['Separate volume from quality','A service business needs enquiries it can actually serve. An ecommerce business needs orders with workable margins. Add sales feedback to your reporting so a low cost per enquiry does not hide poor lead quality.'],['Use a consistent review','Review the same measures each time and note meaningful changes to the offer, creative, audience, or budget. This makes decisions easier to explain and helps you identify what should be tested next.']]},
 {slug:'why-your-reels-arent-getting-views',title:'Why Your Reels Aren’t Getting Views',category:'Short-form video',description:'Review the opening, framing, message, and next step before adding more effects.',video:'ecommerce',sections:[['Make the opening understandable','Show the subject quickly. A viewer should be able to tell what the video is about without reading a long caption. Start with a recognisable action, a product in use, or a clear statement.'],['Keep one idea in focus','A short video is easier to follow when it develops one message. Remove scenes that repeat the same point or distract from the offer. Use editing to guide attention, and keep captions readable.'],['Respect the viewing environment','Check vertical framing, caption placement, sound-off viewing, and the final call to action. Important information should stay clear of interface elements. Preview the creative on a phone before publishing it.'],['Review more than views','A video with modest reach may still create useful enquiries or purchases. Compare attention measures with the campaign goal and the destination experience. Use those observations to choose the next creative test.']]}
];
